	    LOGGER.info("handling RemoveDepartmentsFromOrganizationEvent " );
	    Organization parentEntity = repository.findById(parentId).get();

		for (UUID childId : children) {
			Department child = registry.project(Department.class, childId);
			parentEntity.getDepartments().remove( child );
		}

	    // ------------------------------------------
